// This node recovers the full Document Agent output
// when Supervisor LLM truncates the HTML content.
// It also normalizes mistaken pass-through email-send templates
// into the JSON shape expected by Route Output Type.

const inputJson = $input.first().json;
const supervisorOutput = inputJson.output || '';
const originalPrompt = $('user promt only').first().json.PromptFinal || '';

const parseSendTemplate = (text) => {
  if (typeof text !== 'string' || !/KIRIMKAN\s+SEKARANG/i.test(text)) {
    return null;
  }

  const normalized = text.replace(/\r/g, '').trim();
  const match = normalized.match(/KIRIMKAN\s+SEKARANG\s+email\s+lengkap\s+dibawah\s+ini\s+ke\s+alamat:\s*([^\n]+)\n+---\n*SUBJECT:\s*([^\n]+)\n+([\s\S]+?)\n*---\s*$/i);

  if (!match) {
    return null;
  }

  return {
    action: 'send',
    to: match[1].trim(),
    subject: match[2].trim(),
    message: match[3].trim(),
  };
};

const recoveredSend = parseSendTemplate(supervisorOutput) || parseSendTemplate(originalPrompt);
if (recoveredSend) {
  return [{
    json: {
      ...inputJson,
      output: JSON.stringify(recoveredSend),
      _recovered_send: true,
    },
  }];
}

// Check if supervisor output has been truncated (no HTML, only closing phrase)
const hasHTML = supervisorOutput.includes('<section') || supervisorOutput.includes('<div') || supervisorOutput.includes('```html');
const isPPTSignal = supervisorOutput.includes('Unduh Presentasi (PDF)');
const isPDFSignal = supervisorOutput.includes('Unduh Dokumen (PDF)');

if (!hasHTML && (isPPTSignal || isPDFSignal)) {
  // Supervisor truncated the HTML - try to recover from intermediate steps
  const steps = inputJson.intermediateSteps || [];

  let fullDocumentOutput = '';

  // Search through intermediate steps for Document Agent tool result
  for (const step of steps) {
    let observation = step?.observation || step?.output || '';
    if (typeof observation === 'string') {
      try {
        const parsed = JSON.parse(observation);
        if (Array.isArray(parsed) && parsed[0]?.output !== undefined) {
          observation = parsed[0].output;
        }
      } catch (e) {}
    }
    if (
      observation.includes('<section') || 
      observation.includes('<div') ||
      (observation.includes('Unduh') && observation.length > 200)
    ) {
      fullDocumentOutput = observation;
      break;
    }
  }

  if (fullDocumentOutput) {
    // Recovered full output from intermediate steps
    return [{ json: { ...inputJson, output: fullDocumentOutput, _recovered: true } }];
  }
}

// No recovery needed or recovery failed - pass through as-is
return [{ json: inputJson }];

let raw = $input.first().json.output || '';

if (raw.includes('Communication_Agent_response')) {
  const outer = JSON.parse(raw);
  const content = JSON.parse(outer.Communication_Agent_response.content);
  raw = content[0].output;
}

raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

const draft = JSON.parse(raw);
const originalPrompt = $('user promt only').first().json.PromptFinal || '';

const extractEmail = (label) => {
  const escapedLabel = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = originalPrompt.match(new RegExp(`${escapedLabel}\\s*:\\s*([^\\n]+)`, 'i'));
  return match?.[1]?.trim() || null;
};

const isReplyRequest = /draft email balasan|balas email|email balasan/i.test(originalPrompt);
const explicitRecipient = extractEmail('Kepada');
const originalSender = extractEmail('Email dari');

if (!draft.to) {
  if (isReplyRequest && originalSender) {
    draft.to = originalSender;
  } else if (explicitRecipient) {
    draft.to = explicitRecipient;
  }
}

const subject = draft.subject || '(tanpa subjek)';
const recipient = draft.to || 'belum ditentukan';
const needsRecipientHint = draft.to ? '' : ' dengan menyebut alamat tujuan jika belum ada';

return [{
  json: {
    output: `Draft email sudah siap.\n\nSubjek: ${subject}\nPenerima: ${recipient}\n\nSilakan review draftnya. Jika sudah sesuai, minta saya kirimkan email ini${needsRecipientHint}.`,
    action_results: {
      email_draft: draft,
    },
  }
}];
